"""Protocol for voice event composition handlers."""

from __future__ import annotations

from typing import ClassVar, List, Protocol, Type, TypeVar, runtime_checkable

from rasa.core.voice.event_composition.events.input_events import InputEvent

RawEventTypes = List[Type[InputEvent]]
E = TypeVar("E", bound=InputEvent, contravariant=True)


@runtime_checkable
class EventCompositionHandler(Protocol[E]):
    """Stateful transformation for voice input events."""

    interested_in: ClassVar[RawEventTypes]

    async def handle(self, event: E) -> None:
        """Handle one input event and push composed events when needed."""
        ...


@runtime_checkable
class PendingEventHandler(Protocol):
    """Handler with state that can emit pending events at a batch boundary."""

    async def flush_pending_events(self) -> None:
        """Push any buffered events that should be visible after a raw batch."""
        ...
